/**
 * 🎴 مستوى — بطاقة صورة بتفاصيل حسابك ومستواك (صورة الحساب، المستوى، الخبرة، الرصيد، الرتبة، المخزون، الترتيب).
 *   .مستوى            بطاقتك
 *   .مستوى @شخص       بطاقة شخص آخر (أو ردًا على رسالته)
 * البطاقة تُرسم بالكود بلا مكتبات رسم. الكلمات العربية والأرقام صور حروف مضمّنة في هذا الملف،
 * فلا يلزم أي خط. مكتبة axios تجلب صورة الحساب، وإن فشل الجلب تظهر صورة بديلة.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const zlib = require('zlib');

let axios = null;
try { axios = require('axios'); } catch (e) { /* بدون axios نستعمل صورة بديلة */ }
let decodeImage = () => null;
try { decodeImage = require('../../utils/marryImage').decodeImage || decodeImage; } catch (e) { /* تجاهل */ }

/* ═══════════ حروف مضمّنة (قناع شفافية لكل حرف/كلمة) ═══════════ */
const MASKS = {"labels":{"title":{"w":360,"h":72,"d":""},"level":{"w":237,"h":72,"d":""},"xp":{"w":165,"h":72,"d":""},"points":{"w":177,"h":72,"d":""},"rank":{"w":146,"h":72,"d":""},"inv":{"w":228,"h":72,"d":""},"pos":{"w":194,"h":72,"d":""},"r0":{"w":157,"h":72,"d":""},"r1":{"w":172,"h":72,"d":""},"r2":{"w":191,"h":72,"d":""},"r3":{"w":120,"h":72,"d":""},"r4":{"w":223,"h":72,"d":""},"r5":{"w":250,"h":72,"d":""},"next":{"w":422,"h":72,"d":""}},"digits":{"0":{"w":88,"h":106,"d":""},"1":{"w":88,"h":106,"d":"eNrt1SEMAWEchvHDKYKiaoIiyDebdElRFEGQpa9QdEG4okqKpF9QBFVSJF34Nptk/qbYbNjd5xO454lv+NXXcf6pVKk1Cg/yrKYhmS63x0stLzNwM5VOsDrK++K52Wp3sj5JhOK5A4kaLi5u0t39YtgoWnUvu3nfL9w215Z73s5UPX/fbLhqM+15ucfNtfpDuLi4uLi4uLi4uLi4uLi4uLhfdbV8UA0XFxcX19QlIqLf7gozPPpU"},"2":{"w":88,"h":106,"d":""},"3":{"w":88,"h":106,"d":""},"4":{"w":88,"h":106,"d":""},"5":{"w":88,"h":106,"d":""},"6":{"w":88,"h":106,"d":""},"7":{"w":88,"h":106,"d":""},"8":{"w":88,"h":106,"d":""},"9":{"w":88,"h":106,"d":""},",":{"w":50,"h":106,"d":"eNpjYBgFo2AUjIJRMApGwSgYBaNgFIyC4QoO/McCIkZ1jOoY1UEvHY+waHgjhkeDOjYrovFZkY1Fwya8BcN6TA3vpfBpYH6PqSMJrxXmmBp24i+tajA0fJIjtXzLxK+B6ye6hv2M+HV4oGv4qkyg0O1B15FPqJi+iKbhKBMBDaL/UDV8VydkRSSaFWUE6465qBpOMxPU8QBFw08dghpUUa2oJVyhZaFouMBKWMc6ZA2/DQlrYHqHrKOFiFrWDFnDVXYidFQhafhrjk8lANx76l0="},"/":{"w":48,"h":106,"d":""},"#":{"w":105,"h":106,"d":""},"%":{"w":124,"h":106,"d":""},".":{"w":50,"h":106,"d":"eNrtyzENADAIADBkIhdnmwE+wkPavxEAAABX1WukYRjG9gBmPplW42w="}},"labelBandH":72,"digitBandH":106};

const maskCache = {};
function mask(group, key) {
    const id = group + '|' + key;
    if (maskCache[id]) return maskCache[id];
    const m = MASKS[group] && MASKS[group][key];
    if (!m) return null;
    return (maskCache[id] = { w: m.w, h: m.h, a: zlib.inflateSync(Buffer.from(m.d, 'base64')) });
}

/* ═══════════ الرسم ═══════════ */
const W = 960, H = 540;
const TIERS = [1, 5, 10, 20, 35, 50];   // يطابق RANKS في utils/helpers.js
const ACCENTS = [[120, 205, 195], [110, 222, 125], [96, 165, 255], [255, 153, 64], [255, 208, 70], [232, 105, 255]];
const WHITE = [255, 255, 255], INK = [18, 18, 32];
const tierOf = level => TIERS.reduce((t, min, i) => (level >= min ? i : t), 0);
const clamp01 = v => (v < 0 ? 0 : v > 1 ? 1 : v);
const mix = (a, b, t) => a + (b - a) * t;

function blend(d, x, y, c, a) {
    x = Math.floor(x); y = Math.floor(y);
    if (a <= 0 || x < 0 || y < 0 || x >= W || y >= H) return;
    const i = (y * W + x) * 4;
    d[i] += (c[0] - d[i]) * a; d[i + 1] += (c[1] - d[i + 1]) * a; d[i + 2] += (c[2] - d[i + 2]) * a;
}

function background(acc) {
    const d = new Uint8ClampedArray(W * H * 4);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const t = clamp01(x / W * 0.6 + y / H * 0.4);
        let r = mix(16, 40, t) + acc[0] * 0.08, g = mix(18, 26, t) + acc[1] * 0.08, b = mix(36, 74, t) + acc[2] * 0.08;
        if (((x + y) % 52) < 5) { r += 6; g += 6; b += 8; }
        const v = 1 - 0.38 * Math.pow(Math.hypot(x / W - 0.5, y / H - 0.5) * 1.5, 2);
        const i = (y * W + x) * 4;
        d[i] = r * v; d[i + 1] = g * v; d[i + 2] = b * v; d[i + 3] = 255;
    }
    return d;
}

/** مستطيل بزوايا دائرية: color مصفوفة RGB أو دالة (x,y)⇒RGB. stroke>0 يرسم إطارًا فقط */
function roundRect(d, x, y, w, h, rad, color, alpha = 1, stroke = 0) {
    const cx = x + w / 2, cy = y + h / 2;
    for (let py = Math.floor(y) - 1; py <= Math.ceil(y + h) + 1; py++) for (let px = Math.floor(x) - 1; px <= Math.ceil(x + w) + 1; px++) {
        const qx = Math.abs(px + 0.5 - cx) - (w / 2 - rad), qy = Math.abs(py + 0.5 - cy) - (h / 2 - rad);
        const dist = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - rad;
        const a = stroke ? clamp01(stroke / 2 + 0.5 - Math.abs(dist + stroke / 2)) : clamp01(0.5 - dist);
        if (a > 0) blend(d, px, py, typeof color === 'function' ? color(px, py) : color, a * alpha);
    }
}

function drawMask(d, m, x, y, s, c, alpha = 1) {
    const dw = Math.ceil(m.w * s), dh = Math.ceil(m.h * s);
    for (let dy = 0; dy < dh; dy++) for (let dx = 0; dx < dw; dx++) {
        let sum = 0;
        for (let sy = 0; sy < 3; sy++) for (let sx = 0; sx < 3; sx++) {
            const u = Math.min(m.w - 1, Math.floor((dx + (sx + 0.5) / 3) / s));
            const v = Math.min(m.h - 1, Math.floor((dy + (sy + 0.5) / 3) / s));
            sum += m.a[v * m.w + u];
        }
        blend(d, x + dx, y + dy, c, (sum / 9 / 255) * alpha);
    }
}

const LABEL_H = MASKS.labelBandH, DIGIT_H = MASKS.digitBandH;
const numWidth = (str, s) => [...str].reduce((w, ch) => w + (mask('digits', ch) ? mask('digits', ch).w * s : 0), 0);

/** كلمة عربية: align = 'r' (يمين عند x) أو 'c' (منتصف) أو 'l'. h ارتفاع النص بالبكسل. تعيد عرضها */
function label(d, key, x, y, h, c, align = 'r', alpha = 1, maxW = 0) {
    const m = mask('labels', key); if (!m) return 0;
    let s = h / LABEL_H; if (maxW && m.w * s > maxW) s = maxW / m.w;
    const w = m.w * s, left = align === 'r' ? x - w : align === 'c' ? x - w / 2 : x;
    drawMask(d, m, Math.round(left), Math.round(y + (h - m.h * s) / 2), s, c, alpha);
    return w;
}
function number(d, str, x, y, h, c, align = 'r', alpha = 1, maxW = 0) {
    let s = h / DIGIT_H; const nat = numWidth(str, s); if (maxW && nat > maxW) s *= maxW / nat;
    const w = numWidth(str, s); let left = align === 'r' ? x - w : align === 'c' ? x - w / 2 : x;
    const top = Math.round(y + (h - DIGIT_H * s) / 2);
    for (const ch of str) { const m = mask('digits', ch); if (!m) continue; drawMask(d, m, Math.round(left), top, s, c, alpha); left += m.w * s; }
    return w;
}
const fmt = n => Math.floor(Number(n) || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');

function sample(img, u, v) {
    const x = Math.min(img.width - 1.001, Math.max(0, u - 0.5)), y = Math.min(img.height - 1.001, Math.max(0, v - 0.5));
    const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0, out = [0, 0, 0];
    for (const [ox, oy, wgt] of [[0, 0, (1 - fx) * (1 - fy)], [1, 0, fx * (1 - fy)], [0, 1, (1 - fx) * fy], [1, 1, fx * fy]]) {
        const i = ((y0 + oy) * img.width + (x0 + ox)) * 4;
        out[0] += img.data[i] * wgt; out[1] += img.data[i + 1] * wgt; out[2] += img.data[i + 2] * wgt;
    }
    return out;
}

function avatar(d, cx, cy, R, img, acc) {
    const RING = 9, OUT = R + RING;
    for (let py = cy - OUT - 44; py <= cy + OUT + 44; py++) for (let px = cx - OUT - 44; px <= cx + OUT + 44; px++) {
        const dist = Math.hypot(px + 0.5 - cx, py + 0.5 - cy);
        if (dist > OUT - 2) blend(d, px, py, acc, 0.26 * clamp01(1 - (dist - OUT) / 42));   // توهّج
        blend(d, px, py, acc, clamp01(OUT + 0.5 - dist));                                   // الحلقة
    }
    const base = [acc[0] * 0.5, acc[1] * 0.5, acc[2] * 0.5];
    let side = 0, ox = 0, oy = 0;
    if (img) { side = Math.min(img.width, img.height); ox = (img.width - side) / 2; oy = (img.height - side) / 2; }
    for (let py = cy - R - 1; py <= cy + R + 1; py++) for (let px = cx - R - 1; px <= cx + R + 1; px++) {
        const dist = Math.hypot(px + 0.5 - cx, py + 0.5 - cy), a = clamp01(R + 0.5 - dist);
        if (a <= 0) continue;
        let c;
        if (img) {
            c = [0, 0, 0];
            for (const [dx, dy] of [[0.25, 0.25], [0.75, 0.25], [0.25, 0.75], [0.75, 0.75]]) {
                const p = sample(img, ((px + dx - (cx - R)) / (2 * R)) * side + ox, ((py + dy - (cy - R)) / (2 * R)) * side + oy);
                c[0] += p[0] / 4; c[1] += p[1] / 4; c[2] += p[2] / 4;
            }
        } else {                                    // صورة بديلة: شخصية بيضاء على لون الرتبة
            const nx = (px + 0.5 - cx) / R, ny = (py + 0.5 - cy) / R, shade = 1 - 0.2 * ((ny + 1) / 2);
            c = [base[0] * shade, base[1] * shade, base[2] * shade];
            if (nx * nx + (ny + 0.22) * (ny + 0.22) <= 0.09 || (nx / 0.62) ** 2 + ((ny - 0.72) / 0.5) ** 2 <= 1) c = [235, 238, 245];
        }
        blend(d, px, py, c, a);
    }
}

/** يرسم البطاقة كاملة ويعيد بكسلات RGBA */
function makeCard({ level, xp, need, points, inventory, position, total, img }) {
    const tier = tierOf(level), acc = ACCENTS[tier];
    const d = background(acc);
    const XR = 620, XL = 50, pct = need > 0 ? clamp01(xp / need) : 0;

    // العنوان وخط تحته
    label(d, 'title', 910, 24, 44, acc, 'r');
    for (let x = XL; x <= 910; x++) for (let t = 0; t < 3; t++) blend(d, x, 86 + t, acc, 0.85 * (1 - 0.7 * (x - XL) / 860));

    // المستوى
    label(d, 'level', XR, 106, 32, [190, 196, 220], 'r');
    number(d, String(level), XR, 142, 104, WHITE, 'r');

    // الخبرة
    label(d, 'xp', XR, 262, 30, [190, 196, 220], 'r');
    number(d, `${fmt(xp)}/${fmt(need)}`, XR, 298, 32, WHITE, 'r', 1, 400);
    number(d, `${Math.floor(pct * 100)}%`, XL, 298, 32, acc, 'l');
    roundRect(d, XL, 344, XR - XL, 30, 15, WHITE, 0.1);
    if (pct > 0) {
        const fw = Math.max(30, Math.round((XR - XL) * pct));
        roundRect(d, XR - fw, 344, fw, 30, 15, (px) => { const t = clamp01((XR - px) / (XR - XL)); return [mix(acc[0], 255, t * 0.4), mix(acc[1], 255, t * 0.4), mix(acc[2], 255, t * 0.4)]; });
    }
    const lw = label(d, 'next', XR, 382, 24, [150, 156, 184], 'r');
    number(d, fmt(Math.max(0, need - xp)), XR - lw - 14, 382, 24, [200, 205, 226], 'r');

    // ثلاث بطاقات صغيرة: الرصيد، المخزون، الترتيب
    const boxes = [['points', fmt(points)], ['inv', String(inventory)], ['pos', `#${position}`]];
    boxes.forEach(([key, val], i) => {
        const bx = XR - 176 - i * 192, by = 430;
        roundRect(d, bx, by, 176, 84, 16, WHITE, 0.07);
        roundRect(d, bx, by, 176, 84, 16, acc, 0.5, 2);
        label(d, key, bx + 88, by + 10, 22, [170, 176, 204], 'c');
        number(d, val, bx + 88, by + 40, 34, WHITE, 'c', 1, 150);
    });

    // الصورة الشخصية ولقب الرتبة
    const cx = 775;
    avatar(d, cx, 238, 118, img, acc);
    roundRect(d, cx - 150, 392, 300, 62, 31, acc, 1);
    roundRect(d, cx - 150, 392, 300, 62, 31, WHITE, 0.35, 2);
    label(d, 'r' + tier, cx, 392 + 10, 42, INK, 'c', 1, 250);
    for (let i = 0; i < 6; i++) {
        const dx = cx - 75 + i * 30;
        for (let py = 478; py <= 498; py++) for (let px = dx - 10; px <= dx + 10; px++) {
            const dist = Math.hypot(px + 0.5 - dx, py + 0.5 - 488);
            blend(d, px, py, i <= tier ? acc : WHITE, clamp01(7.5 - dist) * (i <= tier ? 1 : 0.16));
        }
    }
    return d;
}

/** ترميز PNG بمكتبة zlib المدمجة */
const CRC = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = buf => { let c = 0xffffffff; for (const b of buf) c = CRC[(c ^ b) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body));
    return Buffer.concat([len, body, crc]);
}
function encodePng(rgba) {
    const stride = W * 4, raw = Buffer.alloc((stride + 1) * H);
    for (let y = 0; y < H; y++) Buffer.from(rgba.buffer, rgba.byteOffset + y * stride, stride).copy(raw, y * (stride + 1) + 1);
    const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(W, 0); ihdr.writeUInt32BE(H, 4); ihdr[8] = 8; ihdr[9] = 6;
    return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw, { level: 6 })), chunk('IEND', Buffer.alloc(0))]);
}

/* ═══════════ الأمر ═══════════ */
const call = (api, method, ...args) => new Promise(resolve => {
    try { api[method](...args, (err, data) => resolve(err ? null : data)); } catch (e) { resolve(null); }
});
async function fetchAvatar(url) {
    if (!url || !axios) return null;
    try {
        const res = await axios.get(url, { responseType: 'arraybuffer', timeout: 8000, maxContentLength: 5 * 1024 * 1024 });
        return Buffer.from(res.data);
    } catch (e) { return null; }
}

module.exports.config = {
    name: 'مستوى', aliases: ['level', 'lvl', 'لفل', 'بطاقتي', 'card'],
    description: 'بطاقة صورة بتفاصيل حسابك ومستواك أو مستوى شخص آخر',
    usage: 'مستوى [@شخص]', category: 'economy', cooldown: 10, adminOnly: false
};

module.exports.run = async ({ api, event, args, helpers, states, deco }) => {
    const uid = helpers.getTarget(event, args) || String(event.senderID);
    const d = states.getData(uid);
    const name = await helpers.getName(api, uid);
    const need = helpers.xpNeeded(d.level);
    const inventory = Array.isArray(d.inventory) ? d.inventory.length : 0;
    const ranking = Object.entries(states.getAll()).sort((a, b) => b[1].level - a[1].level || b[1].xp - a[1].xp);
    const position = Math.max(1, ranking.findIndex(([id]) => String(id) === String(uid)) + 1);
    const pct = need > 0 ? Math.floor(Math.min(1, d.xp / need) * 100) : 0;
    const body = [`🎴 بطاقة ${name}`, `🏅 الرتبة: ${d.rank || helpers.rankFor(d.level)}`, `⭐ المستوى: ${d.level}`,
        `✨ الخبرة: ${helpers.fmt(d.xp)}/${helpers.fmt(need)} (${pct}%)`, `💰 الرصيد: ${helpers.fmt(d.points)}`,
        `🎒 المخزون: ${inventory}`, `🏆 الترتيب: #${position} من ${ranking.length}`].join('\n');

    let file = null;
    try {
        const info = (await call(api, 'getUserInfo', [uid])) || {};
        const u = info[uid] || {};
        const img = decodeImage(await fetchAvatar(u.thumbSrc || u.avatar || u.profilePicture || null));
        const rgba = makeCard({ level: d.level, xp: d.xp, need, points: d.points, inventory, position, total: ranking.length, img });
        file = path.join(os.tmpdir(), `kira-level-${Date.now()}-${Math.floor(Math.random() * 1e6)}.png`);
        fs.writeFileSync(file, encodePng(rgba));
    } catch (e) {
        console.error('level card:', e && e.message);
        return helpers.reply(api, event, deco.infoBox('🎴 بطاقة الحساب', body));
    }
    const stream = fs.createReadStream(file);
    stream.on('error', () => {});
    api.sendMessage({ body, attachment: stream }, event.threadID, err => {
        fs.unlink(file, () => {});
        if (err) helpers.reply(api, event, deco.infoBox('🎴 بطاقة الحساب', body));
    }, event.messageID);
};

module.exports.__test = { makeCard, encodePng, W, H };
